        Validating --> Failed : invalid
        Executing --> [*]
        Failed --> [*]
    }";
    let first = mmdflux::render_diagram(input, OutputFormat::Text, &RenderConfig::default())
        .expect("first render should succeed");
    for i in 1..=10 {
